<?php
require __DIR__.'/app/bootstrap.php';
$message='اگر این ایمیل در سیستم ثبت شده باشد، لینک بازیابی ارسال می‌شود.';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim((string)($_POST['email']??''));if(filter_var($email,FILTER_VALIDATE_EMAIL)){$q=$pdo->prepare('SELECT id,email FROM users WHERE email=? AND is_active=1');$q->execute([$email]);if($u=$q->fetch()){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$pdo->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at,created_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE),NOW())')->execute([$u['id'],$hash]);$url=site_url('reset-password.php?token='.$token);$from=$config['mail']['from']??'no-reply@example.com';$subject='بازیابی رمز عبور ADVERSING';$body="برای تعیین رمز جدید تا ۳۰ دقیقه آینده از این لینک استفاده کنید:\n$url\nاگر این درخواست را نداده‌اید، این پیام را نادیده بگیرید.";$headers="From: ".$from."\r\nContent-Type: text/plain; charset=UTF-8";@mail($u['email'],$subject,$body,$headers);}}}
render_header('بازیابی رمز عبور');?><main class="container"><div class="form-card narrow"><h1>بازیابی رمز عبور</h1><p><?=e($message)?></p><form method="post"><?=csrf_field()?><div class="form-group"><label>ایمیل حساب</label><input type="email" name="email" required autocomplete="email"></div><button class="btn">ارسال لینک بازیابی</button></form></div></main><?php render_footer();
